import test from'node:test';import assert from'node:assert/strict';import{simulate,DEFAULT_TRAINING,INITIAL_SKILLS}from'./engine.js';
test('person-time and demand are conserved and gained knowledge is bounded',()=>{for(const scenario of['product','battery','pivot'])for(const enabled of[false,true]){const r=simulate({scenario,training:{...DEFAULT_TRAINING,enabled}});for(const h of r.history){assert.ok(Math.abs(h.arrived-h.delivered-h.totalBacklog)<1e-8);h.present.forEach((present,p)=>{const worked=h.allocations.filter(a=>a.person===p).reduce((s,a)=>s+a.time,0);const coached=h.coaching&&[1,3].includes(p)?.35:0;assert.ok(Math.abs(worked+coached+h.idle[p]-(present?1:0))<1e-8);});assert.ok(h.levels.flat().every(x=>x>=0&&x<=1));}}});
test('coaching after mentor absence cannot transfer knowledge or consume either person’s time',()=>{const r=simulate({training:{...DEFAULT_TRAINING,start:13},absence:{person:1,from:12}});assert.equal(r.final.learningTime,0);assert.ok(r.history.slice(12,18).every(h=>h.blockedCoaching));});
test('learning occurs after this week’s work and can leave durable coverage',()=>{const r=simulate(),before=INITIAL_SKILLS[3][1];const first=r.history[1];assert.ok(first.coachingGain>0);assert.ok(first.levels[3][1]>first.before[3][1]);assert.ok(r.final.levels[3][1]>before);assert.deepEqual(r.skills,INITIAL_SKILLS);const plain=simulate({training:{...DEFAULT_TRAINING,enabled:false}});assert.deepEqual(r.history.map(h=>h.demand),plain.history.map(h=>h.demand));});
